// ============================================================
document.getElementById('authSenha').addEventListener('keydown', e => {
  if (e.key === 'Enter') enviarAuth();
});
document.getElementById('authEmail').addEventListener('keydown', e => {
  if (e.key === 'Enter') enviarAuth();
});

verificarSessao();
